with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التنبؤ التشغيلي ومراقبة الظواهر والخدمات المناخية','سير التنبؤ الآني والظواهر الجوية المتخصصة ومراقبة الجفاف والخدمات المناخية ودراسات الحالات.',14,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'عمليات التنبؤ والتنبؤ قصير المدى',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'توقع الظواهر الجوية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'المناخ والمخاطر والإنذار',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الممارسة والتحليل التطبيقي',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('operational-forecast-workflow','سير العمل التشغيلي لإعداد التوقعات الجوية','من استلام الرصد إلى التحليل وإنتاج التوقع ومراجعته وتحديثه.','{"blocks":[{"type":"text","text":"تبدأ دورة التنبؤ بجمع الرصد السطحي والعلوي وبيانات الأقمار والرادار ومخرجات النماذج."},{"type":"text","text":"تخضع البيانات لفحوص الجودة والتوقيت والموقع والوحدات قبل استخدامها في التحليل."},{"type":"text","text":"يحدد المحلل الحالة الراهنة من خلال مقارنة المشاهدات بالخرائط السطحية والعليا والصور الفضائية والرادارية."},{"type":"text","text":"تستخدم النماذج العددية كإرشاد أساسي، مع مقارنة أكثر من نموذج وفحص اتساقها مع الرصد."},{"type":"text","text":"يُبنى التوقع على سيناريو جوي متكامل يحدد الأنظمة المؤثرة وتطورها ومجالات عدم اليقين."},{"type":"text","text":"تُراجع العناصر المحلية مثل التضاريس والسواحل والغطاء الأرضي وتأثيرها في الطقس المتوقع."},{"type":"text","text":"تُحدد فترات التوقع ومناطقها بوضوح، وتفصل التوقعات العامة عن التحذيرات الخاصة."},{"type":"text","text":"تسجل أسباب التعديلات التي يجريها المتنبئ على مخرجات النماذج، لتسهيل التقييم اللاحق."},{"type":"text","text":"تستخدم خرائط العمل وقوائم الفحص لضمان عدم إغفال عناصر مهمة أثناء المناوبة."},{"type":"text","text":"يتطلب تسليم المناوبة توثيق الحالة الحالية والأنظمة المتوقعة والتنبيهات والبيانات الناقصة."},{"type":"text","text":"مثال: إذا أظهر الرادار تطوراً لا تمثله النماذج، يعاد تقييم التوقع قصير المدى وتوثق أسباب التعديل."},{"type":"callout","text":"خلاصة: التنبؤ التشغيلي عملية متكررة تجمع الرصد والتحليل والنماذج والخبرة والتواصل."}]}',660,55,'["تحديد مراحل دورة التنبؤ","دمج الرصد والتحليل والنماذج","تنظيم التحديثات والتسليم التشغيلي"]','عمليات التنبؤ والتنبؤ قصير المدى'),
('nowcasting-and-radar-extrapolation','التنبؤ الآني ومتابعة تطور الخلايا','التنبؤ خلال الساعات القليلة المقبلة باستخدام الرادار والأقمار والرصد المتكرر.','{"blocks":[{"type":"text","text":"التنبؤ الآني Nowcasting يركز على الحالة الراهنة والتغير المتوقع خلال الساعات القليلة المقبلة."},{"type":"text","text":"يعتمد على تحديثات متكررة للرادار والأقمار الصناعية والبرق والمحطات الأرضية."},{"type":"text","text":"تحدد صور الرادار مواقع مناطق الهطول وشدتها النسبية وحركتها وتطور بنيتها."},{"type":"text","text":"يمكن تقدير الحركة قصيرة المدى بمقارنة مواقع الخلايا في صور متتابعة، مع مراعاة تغير الشكل والشدة."},{"type":"text","text":"الاستقراء الحركي يفترض استمرار الحركة المرصودة لفترة قصيرة، لكنه لا يمثل وحده نمو الخلايا أو اضمحلالها."},{"type":"text","text":"تساعد صور القنوات تحت الحمراء وبخار الماء في رصد قمم السحب الباردة وتطور الحمل العميق."},{"type":"text","text":"تضيف بيانات البرق مؤشراً زمنياً على النشاط الكهربائي داخل العواصف، لكنها لا تقيس الهطول مباشرة."},{"type":"text","text":"تؤثر التضاريس وحدود الهبات والتقارب المحلي في نشوء خلايا جديدة لا يمكن توقعها بالاستقراء البسيط."},{"type":"text","text":"تتدهور مهارة الاستقراء مع الزمن عندما تتغير الخلايا أو تتكون خلايا جديدة أو تندمج أنظمة قائمة."},{"type":"text","text":"ينبغي بيان وقت آخر صورة ومصدر البيانات وفترة صلاحية المنتج للمستخدم."},{"type":"text","text":"مثال: قد تتحرك منطقة الصدى نحو مدينة، لكن نمو خلية جديدة على حافتها قد يغير توقيت التأثير ومساره."},{"type":"callout","text":"خلاصة: التنبؤ الآني يمزج تتبع الحركة مع تشخيص التطور الديناميكي والتحديث المستمر."}]}',670,55,'["تعريف التنبؤ الآني","قراءة حركة الخلايا وتطورها","فهم حدود الاستقراء الراداري"]','عمليات التنبؤ والتنبؤ قصير المدى'),
('precipitation-forecasting','التنبؤ بالهطول المطري وتوزيعه المكاني','العوامل المؤثرة في كمية المطر وشدته ومدته وتوزيعه المكاني.','{"blocks":[{"type":"text","text":"يتطلب التنبؤ بالهطول تحديد آلية الرفع ومصدر الرطوبة والاستقرار ومدة بقاء النظام فوق المنطقة."},{"type":"text","text":"تؤثر الجبهات والأخاديد والحمل الحراري والتضاريس والتقارب في مكان تشكل الهطول."},{"type":"text","text":"تختلف كمية الهطول المتراكمة عن الشدة اللحظية؛ فقد ينتج تراكم كبير من مطر متوسط يستمر طويلاً."},{"type":"text","text":"تتغير دقة التوقع المكاني بحسب نوع الحالة؛ فالهطول الحملي المحلي أصعب تحديداً من الهطول الجبهي الواسع أحياناً."},{"type":"text","text":"تستخدم خرائط الهطول النموذجية والرادار ومقاييس المطر والأقمار لتقدير التوزيع والشدة."},{"type":"text","text":"قد تنحاز تقديرات الرادار بسبب حجب الشعاع أو التوهين أو اختلاف علاقة الانعكاسية بمعدل المطر."},{"type":"text","text":"تتأثر تقديرات الأقمار بخصائص السحب والسطح وخوارزمية الاسترجاع، لذلك تقارن ببيانات أرضية."},{"type":"text","text":"تساعد احتمالات تجاوز عتبات مطرية على وصف المخاطر بدلاً من تقديم قيمة وحيدة غير مؤكدة."},{"type":"text","text":"يجب الانتباه إلى اختلاف فترة التجميع والوحدات، مثل mm/h مقابل mm خلال 24 ساعة."},{"type":"text","text":"تُقيّم التوقعات بمقارنة التراكمات مع محطات موثوقة وباستخدام مقاييس كمية وفئوية مناسبة."},{"type":"text","text":"مثال: توقع 30 mm خلال 24 ساعة لا يعني هطولاً منتظماً؛ افحص التوقيت والشدة القصوى وفترات الانقطاع."},{"type":"callout","text":"خلاصة: توقع المطر يجمع الآلية الجوية والقياسات المتعددة والاحتمالات والتحقق."}]}',680,55,'["تحليل بيئة الهطول","التمييز بين الشدة والتراكم","تقييم منتجات المطر"]','توقع الظواهر الجوية'),
('temperature-forecasting-and-boundary-layer','التنبؤ بدرجات الحرارة والطبقة الحدية','تأثير الإشعاع والغطاء السحابي والرياح والرطوبة والتضاريس في الحرارة.','{"blocks":[{"type":"text","text":"يتأثر التغير اليومي للحرارة بالإشعاع الشمسي والحراري وخصائص السطح والخلط الرأسي."},{"type":"text","text":"يساعد الغطاء السحابي على تقليل التسخين النهاري في كثير من الحالات، وقد يحد من الفقد الإشعاعي ليلاً."},{"type":"text","text":"تؤثر سرعة الرياح والخلط في نقل الحرارة وتجانس الطبقة القريبة من السطح."},{"type":"text","text":"يسهم نوع السطح ورطوبة التربة والغطاء النباتي والارتفاع في اختلاف درجات الحرارة محلياً."},{"type":"text","text":"قد يؤدي الهواء الجاف والسماء الصافية والرياح الهادئة إلى تبريد إشعاعي ليلي قوي في ظروف مناسبة."},{"type":"text","text":"تحد السحب والرياح أحياناً من تشكل الانقلابات السطحية، لكن النتيجة تعتمد على بنية الطبقة الحدية."},{"type":"text","text":"تؤثر التضاريس والتجمعات الحضرية والسواحل في درجات الحرارة المرصودة مقارنة بتمثيل النموذج."},{"type":"text","text":"يجب التمييز بين حرارة الهواء القياسية قرب السطح وحرارة سطح الأرض المسترجعة من الأقمار."},{"type":"text","text":"تقارن توقعات الحدين الأدنى والأعلى بملفات الرصد وسجل الانحياز لكل محطة أو منطقة."},{"type":"text","text":"تساعد تصحيحات الارتفاع والانحياز المحلي على تحسين المخرجات، شرط ألا تستبدل التقييم المستقل."},{"type":"text","text":"مثال: توقع حرارة دنيا أعلى من الواقع قد يرتبط بسحب أقل من المرصود أو رياح أضعف أو تمثيل غير دقيق للسطح."},{"type":"callout","text":"خلاصة: التوقع الحراري الجيد يحتاج فهم الإشعاع والطبقة الحدية والخصائص المحلية."}]}',690,55,'["تحليل العوامل المتحكمة بالحرارة","فهم التبريد الليلي والتسخين النهاري","مراجعة الانحياز الحراري للنماذج"]','توقع الظواهر الجوية'),
('wind-forecasting-and-gusts','التنبؤ بالرياح والهبات والقص','توقع سرعة الرياح واتجاهها والهبات والاختلاف بين السطح والطبقات العليا.','{"blocks":[{"type":"text","text":"تتحدد الرياح واسعة النطاق من تدرج الضغط ودوران الأرض، بينما تعدل التضاريس والاحتكاك اتجاهها وسرعتها قرب السطح."},{"type":"text","text":"تختلف سرعة الرياح المقاسة عند ارتفاعات مختلفة بسبب القص الرأسي وخصائص الطبقة الحدية."},{"type":"text","text":"الهبة زيادة قصيرة المدة في سرعة الرياح مقارنة بالرياح المستمرة وفق تعريف فترة القياس المعتمد."},{"type":"text","text":"قد تنتج الهبات عن الخلط الهابط من طبقات أعلى أو الجبهات أو العواصف الحملية أو القنوات التضاريسية."},{"type":"text","text":"تساعد خرائط تدرج الضغط والرياح عند المستويات المنخفضة والعليا في تشخيص بيئة الرياح."},{"type":"text","text":"يؤثر استقرار الطبقة الحدية في قدرة الزخم من الأعلى على الوصول إلى السطح."},{"type":"text","text":"تتطلب توقعات الرياح الساحلية مراعاة نسيم البحر والبر والتباين الحراري بين اليابسة والماء."},{"type":"text","text":"قد تسرع الممرات الجبلية الرياح محلياً أو تغير اتجاهها، ويصعب تمثيل التفاصيل إذا كانت الشبكة خشنة."},{"type":"text","text":"تُقارن سرعة الرياح المتوسطة والهبات القصوى كل على حدة لأن لكل منهما تعريفاً وفترة تجميع مختلفة."},{"type":"text","text":"تستخدم بيانات المحطات والأبراج والرادار والنماذج للتحقق من التوقعات، مع مراعاة ارتفاع الحساس وموقعه."},{"type":"text","text":"مثال: قد تشير خرائط الطبقات العليا إلى رياح قوية، لكن وصولها إلى السطح يعتمد على الخلط والاستقرار."},{"type":"callout","text":"خلاصة: توقع الرياح يتطلب ربط المجال واسع النطاق بالطبقة الحدية والتضاريس وطبيعة الهبات."}]}',700,55,'["تحليل تدرج الضغط والرياح","تفسير الهبات والخلط","تمييز الرياح المستمرة عن القص"]','توقع الظواهر الجوية'),
('fog-visibility-and-low-clouds','الضباب ومدى الرؤية والسحب المنخفضة','شروط تشكل الضباب وأنواعه والعوامل المؤثرة في الرؤية الأفقية.','{"blocks":[{"type":"text","text":"الضباب سحب قريبة من سطح الأرض تقلل الرؤية الأفقية، ويرتبط تشكله بارتفاع الرطوبة إلى الإشباع قرب السطح."},{"type":"text","text":"ضباب الإشعاع يتشكل غالباً ليلاً مع فقد السطح للحرارة وصفاء نسبي ورياح خفيفة ورطوبة مناسبة."},{"type":"text","text":"ضباب الانتقال أو الحمل الأفقي يحدث عندما يتحرك هواء رطب فوق سطح أبرد فيبرد إلى الإشباع."},{"type":"text","text":"قد ينتج الضباب الجبهي أو ضباب الهطول عندما يتبخر المطر في هواء أبرد ويرفع رطوبته حتى الإشباع."},{"type":"text","text":"يساعد تقارب درجة الحرارة من درجة الندى في تقييم قابلية تشكل الضباب، لكنه لا يكفي وحده."},{"type":"text","text":"تؤثر سرعة الرياح في خلط الهواء؛ فالهدوء الشديد قد يحد من عمق الضباب، والرياح القوية قد تشتته أو تغير نوعه."},{"type":"text","text":"تؤثر خصائص السطح والرطوبة والتضاريس والمسطحات المائية في مكان تشكل الضباب واستمراره."},{"type":"text","text":"تقل الرؤية أيضاً بسبب الغبار والدخان والرذاذ والهطول، وليس الضباب وحده."},{"type":"text","text":"يجب التمييز بين مدى الرؤية الأفقية وارتفاع قاعدة السحب، فهما عنصران مختلفان في الرصد والتنبؤ."},{"type":"text","text":"تستخدم تقارير METAR وصور الأقمار والمحطات لتحديد التغير المكاني والزمني للرؤية والضباب."},{"type":"text","text":"مثال: انخفاض فرق الحرارة ونقطة الندى مع رياح هادئة بعد غروب الشمس قد يدعم احتمال ضباب إشعاعي إذا توفرت الرطوبة."},{"type":"callout","text":"خلاصة: التنبؤ بالضباب يتطلب تشخيص التبريد والرطوبة والخلط ومصادر انخفاض الرؤية الأخرى."}]}',710,55,'["تمييز أنواع الضباب","تحليل نقطة الندى والرياح","تقدير ظروف انخفاض الرؤية"]','توقع الظواهر الجوية'),
('snow-ice-and-winter-weather','الثلوج والجليد والظواهر الشتوية','الملف الحراري والهطول المتجمد والتراكم وتأثير التضاريس.','{"blocks":[{"type":"text","text":"يتحدد نوع الهطول الشتوي من البنية الحرارية الرأسية بين قاعدة السحب وسطح الأرض."},{"type":"text","text":"يسقط الثلج عندما تبقى طبقة الهواء مناسبة لبقاء البلورات متجمدة خلال معظم مسارها."},{"type":"text","text":"قد يتحول الثلج إلى مطر إذا مرت البلورات بطبقة دافئة عميقة بما يكفي لإذابتها."},{"type":"text","text":"قد ينتج المطر المتجمد عندما تذوب البلورات في طبقة دافئة ثم تمر بعمق بارد سطحي لا يكفي لإعادة تجمدها قبل ملامسة الأرض."},{"type":"text","text":"تتكون الحبيبات الجليدية عندما تعيد القطرات المتجمدة أو المطر المتجمد التجمد قبل وصولها إلى السطح."},{"type":"text","text":"يتأثر تراكم الثلوج بدرجة الحرارة السطحية ومحتوى الماء في الثلج وشدة الهطول والرياح والذوبان."},{"type":"text","text":"تؤدي الرياح إلى إعادة توزيع الثلوج وتكوين انجرافات، لذلك قد يختلف العمق محلياً عن معدل الهطول."},{"type":"text","text":"تؤثر التضاريس والارتفاع واتجاه المنحدرات في درجة الحرارة والهطول والذوبان."},{"type":"text","text":"تستخدم الرادارات والأقمار ومحطات الثلج والملف الحراري لتحديد نوع الهطول ومناطق التراكم."},{"type":"text","text":"ينبغي الفصل بين عمق الثلج الجديد ومكافئه المائي؛ فالكثافة تختلف حسب بنية الثلج وظروفه."},{"type":"text","text":"مثال: وجود طبقة دافئة فوق طبقة باردة سطحية يستدعي فحص عمق كل طبقة لتحديد ما إذا كان الهطول مطراً متجمداً أو حبيبات جليدية."},{"type":"callout","text":"خلاصة: توقع الظواهر الشتوية يعتمد على الملف الحراري الكامل وخصائص الهطول والسطح."}]}',720,55,'["تحليل نوع الهطول من الملف الحراري","فهم تراكم الثلوج","تمييز الجليد السطحي عن الثلج"]','توقع الظواهر الجوية'),
('drought-monitoring-and-heatwaves','مراقبة الجفاف وموجات الحر','مؤشرات الجفاف الحراري والزراعي والهيدرولوجي ومراقبة موجات الحر.','{"blocks":[{"type":"text","text":"الجفاف فترة ممتدة من نقص المياه مقارنة بالمعتاد، ويختلف تعريفه بحسب القطاع والفترة المرجعية."},{"type":"text","text":"الجفاف الأرصادي يرتبط بنقص الهطول، والزراعي برطوبة التربة واحتياجات النبات، والهيدرولوجي بانخفاض الجريان والمخزون المائي."},{"type":"text","text":"قد يظهر الجفاف الزراعي بعد فترة قصيرة نسبياً من نقص المطر إذا كانت التربة والمحاصيل حساسة للظروف."},{"type":"text","text":"تستخدم مؤشرات مثل SPI لتقييم شذوذ الهطول على مدد زمنية مختلفة، ويعتمد تفسيرها على طول السجل المرجعي وجودته."},{"type":"text","text":"يستخدم SPEI توازن الهطول والطلب التبخري-النتحي المرجعي، ما يجعله حساساً لتغير الحرارة أيضاً."},{"type":"text","text":"تساعد بيانات رطوبة التربة والتدفق النهري والخزانات في تقييم الجفاف الزراعي والهيدرولوجي."},{"type":"text","text":"موجة الحر فترة من درجات حرارة مرتفعة بصورة ملحوظة مقارنة بالمناخ المحلي والفصل، ويجب تعريف عتبتها ومدة استمرارها."},{"type":"text","text":"تتأثر موجات الحر بالمرتفع الجوي والهبوط والسماء الصافية وجفاف التربة والتغذية الراجعة بين السطح والغلاف الجوي."},{"type":"text","text":"يجب استخدام فترة مناخية مرجعية مناسبة عند حساب الشذوذات ومقارنة المناطق المختلفة."},{"type":"text","text":"تدمج المراقبة المحطات والأقمار وبيانات التربة والهطول والنماذج لتقدير الشدة والامتداد والتطور."},{"type":"text","text":"مثال: قد ينتهي نقص المطر مؤقتاً بينما يستمر الجفاف الهيدرولوجي بسبب تأخر استجابة الأنهار والخزانات."},{"type":"callout","text":"خلاصة: مراقبة الجفاف والحر تتطلب مؤشرات متعددة وتعريفات واضحة وربطاً بالآثار القطاعية."}]}',730,55,'["تمييز أنواع الجفاف","قراءة مؤشرات الجفاف","تحليل موجات الحر"]','المناخ والمخاطر والإنذار'),
('climate-services-and-seasonal-outlooks','الخدمات المناخية والتوقعات الفصلية','الفرق بين التوقعات الجوية والمناخية واستخدام الاحتمالات في التخطيط.','{"blocks":[{"type":"text","text":"يركز التنبؤ الجوي على حالة الطقس خلال مدد قصيرة نسبياً، بينما تصف التوقعات المناخية احتمالات الإحصاءات والأنماط على مدد أطول."},{"type":"text","text":"لا تقدم التوقعات الفصلية عادة تسلسلاً يومياً مؤكداً، بل احتمالات أن تكون المتوسطات أو المجاميع أعلى أو أدنى من المعتاد."},{"type":"text","text":"تعتمد التوقعات الفصلية على الحالة المحيطية والغلافية والاقتران بينهما وعلى النماذج التجميعية."},{"type":"text","text":"تستخدم فئات مثل أعلى من الطبيعي وقريب من الطبيعي وأقل من الطبيعي مع احتمالات معايرة."},{"type":"text","text":"تختلف المهارة المناخية مكانياً وموسمياً ومتغيراً بمتغير، لذلك يجب تقييمها محلياً قبل الاستخدام."},{"type":"text","text":"تقدم الخدمات المناخية معلومات مخصصة لقطاعات الزراعة والمياه والصحة والطاقة وإدارة المخاطر."},{"type":"text","text":"يتطلب تصميم الخدمة فهم قرار المستخدم والمهلة الزمنية ومقياس المكان والمؤشر المناخي المناسب."},{"type":"text","text":"توضح خرائط الشذوذ الفرق عن خط أساس مناخي محدد، ويجب ذكر الفترة المرجعية المستخدمة."},{"type":"text","text":"ينبغي تجنب تفسير احتمال الفئة الأعلى من الطبيعي على أنه مقدار محدد من المطر أو الحرارة."},{"type":"text","text":"تتطلب المنتجات المناخية شرح عدم اليقين والقيود والمهارة وحدود الاستخدام."},{"type":"text","text":"مثال: يستفيد قطاع الزراعة من احتمال موسم أمطار أقل من المعتاد عند دمجه مع حالة التربة وتوقيت الزراعة ومصادر المياه."},{"type":"callout","text":"خلاصة: الخدمة المناخية تحول المعلومات الاحتمالية إلى دعم قرار قطاعي مفهوم ومسؤول."}]}',740,55,'["تمييز التوقع الجوي والفصلي","فهم الاحتمالات المناخية","تكييف المعلومات مع المستخدم"]','المناخ والمخاطر والإنذار'),
('meteorological-case-study-method','منهجية دراسة الحالة الجوية وتحليلها','بناء ملف حالة من الرصد والخرائط والنماذج والتحقق اللاحق.','{"blocks":[{"type":"text","text":"تبدأ دراسة الحالة بتحديد السؤال العلمي والفترة الزمنية والمنطقة والظاهرة المراد تحليلها."},{"type":"text","text":"تجمع البيانات من المحطات والرادار والأقمار والسبر والخرائط والنماذج مع توثيق المصدر والتوقيت والوحدات."},{"type":"text","text":"يُبنى تسلسل زمني للحالة يوضح بداية تطورها ومراحلها وذروتها وانحسارها."},{"type":"text","text":"تستخدم خرائط السطح والمستويات العليا لتحديد الأنظمة واسعة النطاق والكتل الهوائية والجبهات."},{"type":"text","text":"تستخدم ملفات السبر ومؤشرات الاستقرار لفهم البيئة الحرارية والرطوبية والقص قبل الحدث وأثناءه."},{"type":"text","text":"تستخدم صور الرادار والأقمار لتوثيق البنية المكانية وتطور السحب والهطول."},{"type":"text","text":"تقارن التوقعات الصادرة قبل الحدث بالمشاهدات اللاحقة مع تثبيت وقت الإصدار ومهلة التنبؤ."},{"type":"text","text":"يفصل التحليل بين خطأ التوقيت وخطأ الموقع وخطأ الشدة وخطأ نوع الظاهرة."},{"type":"text","text":"توثق الفجوات في البيانات وعدم اليقين وأي قيود في تمثيل الرصد أو النموذج."},{"type":"text","text":"تختتم الدراسة بدروس قابلة للتطبيق وتحسينات محددة في إجراءات الرصد والتحليل والتواصل."},{"type":"text","text":"مثال: دراسة منخفض مطري تتضمن خرائط الضغط والارتفاع والرطوبة والسبر والهطول المرصود وتقييم توقعات النماذج."},{"type":"callout","text":"خلاصة: دراسة الحالة تربط المفاهيم النظرية بقراءة الأدلة وتقييم الأداء وتحسين الممارسة."}]}',750,55,'["تنظيم بيانات دراسة الحالة","بناء تسلسل زمني للحالة","إجراء تقييم بعد الحدث"]','الممارسة والتحليل التطبيقي'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'عمليات التنبؤ والتنبؤ قصير المدى' then u1.id when 'توقع الظواهر الجوية' then u2.id when 'المناخ والمخاطر والإنذار' then u3.id when 'الممارسة والتحليل التطبيقي' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التنبؤ التشغيلي ومراقبة الظواهر والخدمات المناخية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;